\begin{lemma}\label{lem9}
	Suppose Assumptions \ref{asup2} and \ref{asup3} hold. Let $\gamma \in (0, 1/(\rho_{f_2} +\rho_{g_2}) )$ and  $(\bar{x},\bar{y})\in X\times \Re^m$. Then, for any $(x,y) \in X \times \Re^m$, the following inequalities hold,
	\begin{align}
		-v_{\gamma}(x,\bar{y}) &\le -v_{\gamma}(\bar{x},\bar{y})-\langle \nabla_x v_{\gamma}(\bar{x},\bar{y}),x-\bar{x}\rangle +\frac{\rho_{f_1} + \rho_{g_1}}{2}\|\bar{x}-x\|^2,  \label{lem9_eq1} \\
		-v_{\gamma}(\bar{x},y) &\le -v_{\gamma}(\bar{x},\bar{y})-\langle \nabla_y v_{\gamma}(\bar{x},\bar{y}),y-\bar{y}\rangle. \label{lem9_eq2}
	\end{align}
\end{lemma}

\begin{proof}
	According to Proposition \ref{partial_grad_v}, for any $\bar{y} \in \Re^m$, $v_{\gamma}(x, \bar{y})$ is a $(\rho_{f_1} + \rho_{g_1})$-weakly convex function with respect to $x$ on $X$, that is, $v_{\gamma}(x,\bar{y})+\frac{\rho_{f_1} + \rho_{g_1}}{2}\|x\|^2$ is convex on $X$. Then we can obtain \eqref{lem9_eq1} immediately. The second inequality \eqref{lem9_eq2} follows from Proposition \ref{partial_grad_v} that for any $\bar{x} \in X$, $v_{\gamma}(\bar{x}, y)$ is convex with respect to $y$.
\end{proof}

\begin{lemma}\label{lem1}
	Suppose Assumptions \ref{asup1}, \ref{asup2} and \ref{asup3} hold. Let $\gamma \in (0, 1/(\rho_{f_2} +\rho_{g_2}) )$, $\alpha_k \in [0, 2/(L_{\psi_{x,k}} + c_\alpha)]$ and $\beta_k \in [0, 2/(L_{\psi_{y,k}} + c_\beta)]$, where $L_{\psi_{x,k}} = L_{F_x}/p_k+L_{f_x}+L_{g_1}+\rho_{f_1} + \rho_{g_1}$, $L_{\psi_{y,k}} = L_{F_y}/p_k+L_{f_y}$ and $c_\alpha, c_\beta$ are positive constants. Then, there exists $C_\eta , C_\gamma > 0$ such that the sequence $\{(x^k,y^k,\tilde{y}^k)\}$ generated by AGILS {\rm (}\cref{alg1}{\rm )} satisfies the following inequality,
	\begin{equation}\label{lem1_eq}
		\begin{aligned}
			\tilde{\psi}_{p_{k+1}}\left(x^{k+1}, \tilde{y}^{k+1}\right)\leq\,& \tilde{\psi}_{p_k}\left(x^k, \tilde{y}^k\right) +  \left( \frac{C_\eta^2}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{C_\eta^2}{c_\beta\gamma^2 } \right) \zeta_{k}^2 + C_{\gamma} \zeta_{k+1}^2\\
			&- \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2  -\frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2,
		\end{aligned}
	\end{equation}
	where  $\zeta_{k} := \max\{ s_k,  ( \prod_{i=0}^{k} \tau_i ) \mathcal{G}(\theta^{0}, x^{0}, y^{0})\}$ and $\{ \zeta_{k} \}$ is square summable.
\end{lemma}

\begin{proof}

	First, the update rule for \( y^{k+1} \) given in \eqref{update_y} defines it as the minimizer of the function $ g(x^k, y) + \langle d_y^k, y - \tilde{y}^{k} \rangle + \frac{1}{2\beta_k} \left\| y - \tilde{y}^k \right\|^2$. This function is $1/\beta_k$-strongly convex in $y$. By applying \cite[Theorem 6.39]{beck2017first}, we obtain
	\begin{equation}\label{lem1_eq5}
		g(x^{k}, y^{k+1}) + \langle d_y^k, y^{k+1}-\tilde{y}^k\rangle+\frac{1}{\beta_k}\|y^{k+1}-\tilde{y}^k\|^2 \le g(x^{k}, \tilde{y}^{k}).
	\end{equation}


	According to the assumptions, with $x^{k} \in X$, we have that $\nabla_y F(x^{k},y)$ and $\nabla_y f(x^{k},y)$ are $L_{F_y}$- and  $L_{f_y}$-Lipschitz continuous with respect to variable $y$ on $Y$, respectively, and combine this with \eqref{lem9_eq2}, we have
	\begin{equation}\label{lem1_eq6}
		\begin{aligned}
			&(\tilde{\psi}_{p_k}-g)(x^{k},y^{k+1})  \\
			\le \, & (\tilde{\psi}_{p_k}-g)	(x^{k},\tilde{y}^k) + \langle \nabla_y (\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k),y^{k+1}-\tilde{y}^k\rangle +\frac{L_{\psi_{y,k}}}{2}\|y^{k+1}-\tilde{y}^k\|^2,
		\end{aligned}
	\end{equation}
	where $L_{\psi_{y,k}}=L_{F_y}/p_k+L_{f_y}$. 
	Combining \eqref{lem1_eq5} and \eqref{lem1_eq6} yields
	\begin{equation}\label{lem1_eq7}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,& 	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right) + \langle \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k, y^{k+1}-\tilde{y}^k\rangle  \\
			&-\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
		\end{aligned}
	\end{equation}	
	Using the formula of \( \nabla_y v_\gamma \) in \eqref{valuefinc}, and the construction of $d_y^k$ in \eqref{dy}, we have
	\begin{equation}\label{lem1_eq11}
		\begin{aligned}
			\left\| \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k \right\| & = \| \nabla_y v_\gamma(x^k, \tilde{y}^k) + (\tilde{y}^k-\theta^{k})/\gamma\| \\
			& = \frac{1}{\gamma}\left\| \theta^*_{\gamma}(x^{k},\tilde{y}^k) - \theta^{k} \right\| \le \frac{C_\eta}{\gamma} \mathcal{G}({\theta}^{k}, x^{k}, \tilde{y}^{k}) \le \frac{C_\eta}{\gamma} \zeta_{k},
		\end{aligned}
	\end{equation}
	where the first inequality follows from Lemma \ref{error_bound} and the second inequality is a consequence of the inexactness condition \eqref{inexacty2}. 

	Combining the above inequality with \eqref{lem1_eq7} gives us
	\begin{equation}\label{lem1_eq8}
		\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,  	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right)  - \left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2.
	\end{equation}
	Next, considering the update rule for $x^{k+1}$ given in \eqref{update_x}, we have
	\begin{equation}\label{lem1_eq1}
		\langle d_x^k, x^{k+1}-x^k\rangle+\frac{1}{\alpha_k}\|x^{k+1}-x^k\|^2 \le 0.
	\end{equation}	
	By the assumptions, with $y^{k+1} \in Y$, we have that $\nabla_x F(x, y^{k+1})$, $\nabla_x f(x, y^{k+1})$ and $\nabla_{x} g(x, y^{k+1})$ are $L_{F_x}$-, $L_{f_x}$-, and $L_{g_1}$-Lipschitz continuous with respect to variable $x$ on $X$, respectively, and combine this with \eqref{lem9_eq1}, we have
	\begin{equation}\label{lem1_eq2}
		\tilde{\psi}_{p_k}(x^{k+1}, y^{k+1})\le  \tilde{\psi}_{p_k}	(x^{k}, y^{k+1})+\langle \nabla_x 	\tilde{\psi}_{p_k}(x^{k}, y^{k+1}),x^{k+1}-x^k\rangle+\frac{L_{\psi_{x,k}}}{2}\|x^{k+1}-x^k\|^2,
	\end{equation}
	where $L_{\psi_{x,k}}=L_{F_x}/p_k+L_{f_x}+L_{g_1}+ \rho_{f_1} + \rho_{g_1} $. Combining \eqref{lem1_eq1} and \eqref{lem1_eq2} yields
	\begin{equation}\label{lem1_eq3}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) + \langle \nabla_x \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k,x^{k+1}-x^k\rangle  \\
			&-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}\right)\left\|x^{k+1}-x^k\right\|^2.
		\end{aligned}
	\end{equation}
	Using the formula of the gradient of $v_\gamma$ given in \eqref{valuefinc} and the construction of $d_x^k$ in \eqref{dx}, and the $L_{f_x}$- and $L_{g_2}$-Lipschitz continuity of $\nabla_x f(x^k,y)$ and $\nabla_{x} g(x^k,y)$ with respect to variable $y$ on $Y$, we have
	\begin{equation}\label{lem1_eq10}
		\begin{aligned}
			\left\| \nabla_x  \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k \right\| 
			&= \left\| \nabla_{x} \varphi(x^k, \theta^*_{\gamma}(x^k,y^{k+1})) - \nabla_{x} \varphi(x^k, \theta^{k+1/2}) \right\| \\
			& \le (L_{f_x} + L_{g_2})\left\| \theta^*_{\gamma}(x^k,y^{k+1}) - \theta^{k+1/2} \right\| \le (L_{f_x} + L_{g_2})C_\eta \zeta_{k},
		\end{aligned}
	\end{equation}
	where the last inequality follows from \cref{error_bound} and the inexact criterion \eqref{inexacty1}. Combining the above inequality with \eqref{lem1_eq3} gives us
	\begin{equation}\label{lem1_eq4}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) - \left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}-\frac{c_\alpha}{4}\right)\left\|x^{k+1}-x^k\right\|^2 \\ & + \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2.
		\end{aligned}
	\end{equation}
	Combining  \eqref{lem1_eq8}, \eqref{lem1_eq4}, and then  \eqref{lem1_eq12} established in  Lemma \ref{lem0}, we obtain
	\begin{equation}\label{lem1_eq9}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, \tilde{y}^{k+1}\right)\leq\,& 	\tilde{\psi}_{p_k}\left(x^k, \tilde{y}^k\right)+  \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2 + C_{\gamma} \zeta_{k+1}^2\\
			&\hspace{-50pt}-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}- \frac{c_\alpha}{4} \right)\left\|x^{k+1}-x^k\right\|^2 -\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4} \right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
		\end{aligned}
	\end{equation}
	Because  $\alpha_k \in [0, 2/(L_{\psi_{x,k}} + c_\alpha)]$ and $\beta_k \in [0, 2/(L_{\psi_{y,k}} + c_\beta)]$, and $\tilde{\psi}_{p_{k+1}}(x^{k+1}, \tilde{y}^{k+1}) \leq 	\tilde{\psi}_{p_k}(x^{k+1}, \tilde{y}^{k+1})$ following from the non-decreasing property of the penalty parameter $p_k$ and the non-negative property of $F-\underline{F}$, we can obtain \eqref{lem1_eq} from \eqref{lem1_eq9}.

	Finally, we show that \( \{\zeta_k\} \) is square summable. Let $ \mathcal{G}_0 = \mathcal{G}(\theta^{0}, x^{0}, y^{0})$ and $r_k :=  ( \prod_{i=0}^{k} \tau_i )\mathcal{G}_0 $. Since $\zeta_{k} := \max\{ s_k, r_k\}$, we have $\sum_{k=0}^\infty \zeta_k^2 \le \sum_{k=0}^\infty s_k^2 + \sum_{k=0}^\infty r_k^2$. By assumption, \( \sum_{k=0}^\infty s_k^2 < \infty \). Thus, we only need to show that  \( \{r_k\} \) is square summable. Recall that \( \tau_k = \tau_0/(k+1)^{p_\tau} \) with \( p_\tau > 0 \), then
	\[
	r_k = \left( \prod_{i=0}^{k} \tau_i \right) \mathcal{G}_0  = \tau_0^{k+1} \left( \prod_{i=1}^{k+1} \frac{1}{i^{p_\tau}} \right) \cdot \mathcal{G}_0  = \frac{\tau_0^{k+1}}{((k+1)!)^{p_\tau}}\mathcal{G}_0 .
	\]
	For the ratio test on  $\sum_{k=0}^\infty r_k^2$, we consider 
	\[
	\lim_{k \rightarrow \infty}\frac{r_{k+1}^2}{r_k^2} =  \lim_{k \rightarrow \infty} \frac{\tau_0^2}{(k+2)^{2p_\tau}}  = 0.
	\]
	Therefore, by the ratio test, $\sum_{k=0}^\infty r_k^2 < \infty$, implying that \( \{\zeta_k\} \) is square summable.
\end{proof}

\begin{lemma}\label{lem3}
	The sequence $\left\{(x^k,y^k,\tilde{y}^k)\right\}$ satisfies
	\begin{equation*}
		\sum\limits_{k=0}^{{\infty}}\left\|(x^{k+1},y^{k+1})-(x^k,\tilde{y}^k)\right\|^2<\infty, \quad \text{and} \quad \lim\limits_{k\to\infty}\left\|(x^{k+1},y^{k+1})-(x^k,\tilde{y}^k)\right\|=0.
	\end{equation*}
\end{lemma}

\begin{proof}
	Summing  \cref{lem1_eq} from Lemma \ref{lem1} over $k=0,1,\dots,K-1$ yields,
	\begin{equation}\label{lem3_eq1}
		\begin{aligned}
			\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right)- \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) \leq & -\sum\limits_{k=0}^{K-1} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right)\\& +\sum\limits_{k=0}^{K-1}\left( \frac{C_\eta^2 }{c_\alpha}(L_{f_x} + L_{g_2})^2+ \frac{C_\eta^2}{c_\beta\gamma^2} \right) \zeta_{k}^2+ \sum\limits_{k=0}^{K-1}C_{\gamma} \zeta_{k+1}^2.\\
		\end{aligned}
	\end{equation}
	Since \( \{\zeta_k\} \) is square summable from Lemma \ref{lem1}, it follows that
	\[
	\sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2 < \infty.
	\]
	Additionally, because $\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right) \ge 0$, by taking $K \rightarrow \infty$ in \eqref{lem3_eq1}, we have
	\begin{equation}\label{lem3_eq2}
		\begin{aligned}
			&\quad\,\sum\limits_{k=0}^{\infty} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right) \\
			&\le \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) + \sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2  < \infty,
		\end{aligned}
	\end{equation}
	which proves the result.
\end{proof}

\begin{lemma}\label{lem4}
	Let $\{ (x^{k_j},\tilde{y}^{k_j}) \} $ be any convergent subsequence of iterates $\{(x^k,\tilde{y}^k)\}$ such that $(x^{k_j},\tilde{y}^{k_j})$ satisfies condition \eqref{inexacty_y} with $k = k_j - 1$. 
	If $(x^{k_j},\tilde{y}^{k_j}) \rightarrow (\bar{x},\bar{y}) $ as $j \rightarrow \infty$ for some $(\bar{x},\bar{y}) $, then $\bar{y} \in S(\bar{x})$. 
\end{lemma}

\begin{proposition}\label{prop0}
	Let $\epsilon > 0$. If the sequence $\{p_k\}$ is bounded, then any accumulation point $(\bar{x}, \bar{y})$ of the iterate sequence $\{(x^k, {y}^k)\}$ satisfies
	\[
	\varphi(\bar{x}, \bar{y}) -  v_\gamma(\bar{x},\bar{y}) \le \epsilon.
	\]
\end{proposition}

\begin{proof}
	The proof builds upon techniques used in the proof of Theorem 1 in \cite{ye2023}. 
	Let $(\bar{x}, \bar{y})$ be an accumulation point of the sequence $\{(x^k,y^k)\}$, and let $\{(x^{k_j+1},y^{k_j+1})\}$ be a convergent subsequence such that $(x^{k_j+1},y^{k_j+1}) \rightarrow (\bar{x}, \bar{y})$ as $k_j \rightarrow \infty$. 
	By Lemma \ref{lem3}, we have  $\lim_{k_j \to\infty} \|(x^{k_j+1},y^{k_j+1})-(x^{k_j},\tilde{y}^{k_j}) \|=0$, which implies that $(x^{k_j},\tilde{y}^{k_j}) \to (\bar{x},\bar{y})$ .
	Since $\{p_k\}$ is bounded, there exists $k_0 > 0$ such that $p_k = \bar{p} := p_{k_0}$ for any $k \ge k_0$. 


	From the update rules \eqref{update_x} and \eqref{update_y}, and the expressions for $d_x^k$ and $d_y^k$, we have    
	\begin{equation}\label{th1_eq2}
		\begin{aligned}
			\xi_x^k & \in \nabla_x F(x^{k+1},y^{k+1})+p_k \left(\nabla_x \varphi(x^{k+1},y^{k+1}) - \nabla_x v_\gamma(x^{k+1},y^{k+1})\right) +\mathcal{N}_{X}(x^{k+1}),\\
			\xi_y^k & \in \nabla_y F(x^{k},y^{k+1})+p_k \left(\partial_y \varphi(x^{k},y^{k+1}) - \nabla_y v_\gamma(x^{k},y^{k+1})\right) +\mathcal{N}_{Y}(y^{k+1}),
		\end{aligned}
	\end{equation}
	where $\xi_x^k \in \Re^n$ and $\xi_y^k \in \Re^m$ are given by
	\begin{equation}\label{th1_eq4}
		\begin{aligned}
			\xi_x^k &:=  p_k \left(\nabla_x \tilde{\psi}_{p_{k}}\left(x^{k+1}, y^{k+1} \right) - d_x^k \right)  - \frac{p_k}{\alpha_k}\left(x^{k+1}-x^k\right), \\
			\xi_y^k &:=  p_k \left( \nabla_y\left(\tilde{\psi}_{p_k}-g\right)\left(x^{k}, y^{k+1}\right) - d_y^k \right)-\frac{p_k}{\beta_k}\left(y^{k+1}-\tilde{y}^k\right).
		\end{aligned} 
	\end{equation} 
	We now show that $\xi_x^{k_j}, \xi_y^{k_j} \rightarrow 0$ as $k_j \rightarrow \infty$. First, we have 
	\begin{equation}
		\begin{aligned}
			& \| \nabla_x \tilde{\psi}_{p_{k}}\left(x^{k+1}, y^{k+1} \right) - d_x^k\| \\ \le \, & \|  \nabla_x \tilde{\psi}_{p_{k}}\left(x^{k+1}, y^{k+1} \right) - \nabla_x \tilde{\psi}_{p_{k}}\left(x^{k}, y^{k+1} \right) \| + \| \nabla_x \tilde{\psi}_{p_{k}} \left(x^{k}, y^{k+1} \right) - d_x^k \| \\
			\le \, & \|  \nabla_x \tilde{\psi}_{p_{k}}\left(x^{k+1}, y^{k+1} \right) - \nabla_x \tilde{\psi}_{p_{k}}\left(x^{k}, y^{k+1} \right) \| + (L_{f_x} + L_{g_2})C_\eta \zeta_{k}, 
		\end{aligned}
	\end{equation}
	where the last inequality follows from \eqref{lem1_eq10}. Since $p_k = \bar{p}$ for all $k \ge k_0$, and assuming that $\nabla_{x} F, \nabla_{x} f$ and $\nabla_{x} g$ are continuous on $X \times Y$, and $\nabla_{x} v_\gamma$ is continuous on $X \times Y$ (Proposition \ref{partial_grad_v}), we conclude that $ \nabla_x \tilde{\psi}_{p_{k}} =  \nabla_x \tilde{\psi}_{\bar{p}}$ is continuous on $X \times Y$. 
	As $\lim_{k_j\to\infty} (x^{k_j+1},y^{k_j+1}) = \lim_{k_j\to\infty} (x^{k_j},\tilde{y}^{k_j}) = (\bar{x}, \bar{y})$ and $\zeta_{k} \rightarrow 0$, it follows that $\nabla_x \tilde{\psi}_{p_{k_j}} (x^{k_j+1}, y^{k_j+1} ) - d_x^{k_j} \rightarrow 0$ as $k_j \rightarrow \infty$. Combining this with $ \|x^{k_j+1}-x^{k_j} \| \to 0$ and $\alpha_k \ge \underline{\alpha} > 0$, we obtain from \eqref{th1_eq4} that $\xi_x^{k_j} \rightarrow 0$ as $k_j \rightarrow \infty$.

	A similar argument can be applied to $\xi_y^k$. From \eqref{lem1_eq11}, we have 
	\begin{equation}\label{th1_eq5}
		\begin{aligned}
			& \|\nabla_y\left(\tilde{\psi}_{p_k}-g\right)\left(x^{k}, y^{k+1}\right) - d_y^k \| \\ \le \, & \| \nabla_y\left(\tilde{\psi}_{p_k}-g\right)\left(x^{k}, y^{k+1} \right) - \nabla_y\left(\tilde{\psi}_{p_k}-g\right)\left(x^{k}, \tilde{y}^k \right) \| + {C_\eta}\zeta_{k}/\gamma.
		\end{aligned}
	\end{equation}
	Since $p_k = \bar{p}$ for all $k \ge k_0$, and under the assumption that $\nabla_{y} F$ and $\nabla_{y} f$ are continuous on $X \times Y$, and $\nabla_{y} v_\gamma$ is continuous on $X \times Y$ (Proposition \ref{partial_grad_v}), we have that $ \nabla_y (\tilde{\psi}_{p_{k}} - g) = \nabla_y (\tilde{\psi}_{\bar{p}} - g)$ is continuous on $X \times Y$. As $\lim_{k_j\to\infty} (x^{k_j},y^{k_j+1}) = \lim_{k_j\to\infty} (x^{k_j},\tilde{y}^{k_j}) = (\bar{x}, \bar{y})$ and $\zeta_{k} \rightarrow 0$, it follows that $\nabla_y (\tilde{\psi}_{p_{k_j}} - g)(x^{k_j}, y^{k_j+1} ) - d_y^{k_j} \rightarrow 0$ as $k_j \rightarrow \infty$. Combining this with $ \|y^{k_j+1}-\tilde{y}^{k_j} \| \to 0$ and $\beta_k \ge \underline{\beta} > 0$, we conclude from \eqref{th1_eq5} that $\xi_y^{k_j} \rightarrow 0$ as $k_j \rightarrow \infty$.

	Now, taking the limit as $k = k_j \rightarrow \infty$ in \eqref{th1_eq2}, since $\xi_x^{k_j}, \xi_y^{k_j} \rightarrow 0$, $p_k = \bar{p}$ for all $k \ge k_0$, $\lim_{k_j\to\infty} (x^{k_j+1},y^{k_j+1}) = \lim_{k_j\to\infty} (x^{k_j},y^{k_j+1}) = \lim_{k_j\to\infty} (x^{k_j},\tilde{y}^{k_j}) = (\bar{x}, \bar{y})$, $\nabla F$, $\nabla v_\gamma$, and $\nabla_x \varphi$ are continuous on $X \times Y$, $\partial_y \varphi$ and $\mathcal{N}_{X\times Y}$ are outer semicontinuous on $X \times Y$, and $\partial \varphi = \{\nabla_x \varphi\} \times \partial_y \varphi$ on $X \times Y$, we obtain 
	\begin{equation}\label{th1_eq6}
		0\in\nabla F(\bar{x}, \bar{y})+\bar{p}\left(\partial \varphi(\bar{x},\bar{y})-\nabla v_\gamma(\bar{x}, \bar{y})\right)+\mathcal{N}_{X\times Y}(\bar{x}, \bar{y}).
	\end{equation}

	Finally, from Proposition \ref{prop0}, we know that the limit point $(\bar{x}, \bar{y})$ satisfies $\varphi(\bar{x}, \bar{y}) -  v_\gamma(\bar{x},\bar{y}) \le \epsilon $. Let $\bar{\epsilon}:= \varphi(\bar{x}, \bar{y}) -  v_\gamma(\bar{x},\bar{y}) \in [0, \epsilon]$. Combining this with \eqref{th1_eq6}, we have
	\begin{equation}
		\left\{
		\begin{aligned}
			&0\in\nabla F(\bar{x}, \bar{y}) + \bar{p}\left( \partial \varphi(\bar{x}, \bar{y}) - \nabla v_\gamma(\bar{x}, \bar{y})\right)+\mathcal{N}_{X\times Y}(\bar{x}, \bar{y}),\\
			&\varphi(\bar{x}, \bar{y}) - v_{\gamma}(\bar{x}, \bar{y})- \bar{\epsilon} \le 0, \qquad  \bar{p}\left( \varphi(\bar{x}, \bar{y}) - v_{\gamma}(\bar{x}, \bar{y})- \bar{\epsilon} \right)=0,
		\end{aligned}\right.
	\end{equation}
	which implies that $(\bar{x},\bar{y})$ is a KKT point of problem $({\rm VP})_\gamma^{\bar{\epsilon}}$ with $\bar{\epsilon}\le \epsilon$.
\end{proof}

source_units.raw_tex:
Bilevel optimization problems are a class of hierarchical optimization problems where the feasible region is implicitly defined by the solution set of a lower-level optimization problem. In this work, we focus on a bilevel optimization problem which has a convex composite lower-level problem,
\begin{equation}\label{eq1}
	\begin{aligned}
		\min\limits_{x \in X, y \in Y} &\ F(x,y)\\
		{\rm s.t.}\quad &\ y \in S(x),
	\end{aligned}
\end{equation}
where $S(x)$ denotes the set of optimal solutions to the lower-level problem:
\begin{equation}\label{LL}
	\min\limits_{y \in Y}\ \varphi(x,y) := f(x,y) + g(x,y).
\end{equation}

To overcome this challenge, in this paper, we consider the following Moreau envelope-based reformulation of the bilevel optimization problem \eqref{eq1}, first introduced in \cite{gao2024},
\begin{equation}\label{reformualtion_Moreau}
	({\rm VP})_\gamma \quad\quad
	\min\limits_{x\in X,y\in Y}\  F(x,y) \quad		{\rm s.t.}\quad\ \varphi (x,y)-v_{\gamma} (x,y)\le 0,
\end{equation}

where $v_{\gamma}(x, y)$ is the Moreau envelope associated with the lower-level problem,
\begin{equation}\label{def_vg}
	v_{\gamma}(x,y):=\inf\limits_{\theta\in Y}\varphi(x,\theta)+\frac{1}{2\gamma}\|\theta-y\|^2,
\end{equation}

where $\gamma > 0$. When the lower-level problem is convex with respect to $y$,  this reformulation is equivalent to the original bilevel optimization problem \eqref{eq1} (see \cite[Theorem 1]{gao2024}).  Directional optimality conditions for $({\rm VP})_\gamma$ are discussed in \cite{bai2025optimality}. However, as shown in \cite{gao2024} and \cite[Proposition 7]{ye2023}, classical constraint qualification (CQ) conditions do not hold at any feasible point of $({\rm VP})_\gamma$, motivating us to study the following relaxed approximation problem,
\begin{equation}\label{reformualtion_Moreau_relax}
	({\rm VP})_\gamma^{\epsilon} \quad\quad
	\min\limits_{x\in X,y\in Y}\  F(x,y) \quad		{\rm s.t.}\quad\ \varphi (x,y)-v_{\gamma} (x,y)\le \epsilon,
\end{equation}

This part outlines the assumptions on the problem data for the bilevel optimization problem studied in this work. First, we assume that the upper-level objective $F$ is smooth and bounded below.

\begin{assumption}\label{asup1}
	The function \(F : \mathbb{R}^n \times \mathbb{R}^m \to \mathbb{R}\) is bounded below on \(X \times Y\), i.e., \(\underline{F} := \inf_{(x, y) \in X \times Y} F(x, y) > -\infty\). \(F\) is continuously differentiable, and its gradients \(\nabla_x F\) and \(\nabla_y F\) are \(L_{F_x}\)- and \(L_{F_y}\)-Lipschitz continuous on \(X \times Y\), respectively.
\end{assumption}

Throughout this paper, we focus on cases where the lower-level problem is a convex optimization problem.

\begin{assumption}\label{asup2}
	For any \(x \in X\), the functions \(f(x, \cdot)\) and \(g(x, \cdot)\) are convex and defined on the closed convex set \(Y\). 
\end{assumption}

\begin{assumption}\label{asup3}
	The lower-level objective functions \(f(x, y)\) and \(g(x, y)\) satisfy:
	\begin{itemize}
		\item[(1)] \(f(x, y)\) is continuously differentiable on \(X \times Y\), and its gradients \(\nabla_x f\) and \(\nabla_y f\) are \(L_{f_x}\)- and \(L_{f_y}\)-Lipschitz continuous on \(X \times Y\), respectively;
		\item[(2)] \(g(x, y)\) is continuous on \(X \times Y\), \(\nabla_x g(x, y)\) exists, and \(\nabla_x g(\cdot, y)\) is \(L_{g_1}\)-Lipschitz continuous on \(X\) for any \(y \in Y\), while \(\nabla_x g(x, \cdot)\) is \(L_{g_2}\)-Lipschitz continuous on \(Y\) for any \(x \in X\);
		\item[(3)] \(f(x, y)\) is \((\rho_{f_1}, \rho_{f_2})\)-weakly convex on \(X \times Y\), and \(g(x, y)\) is \((\rho_{g_1}, \rho_{g_2})\)-weakly convex on \(X \times Y\).
	\end{itemize}
\end{assumption}

Under Assumption \ref{asup2}, the solution mapping
\begin{equation}\label{proximal_LL}
	S_{\gamma}(x, y) := \mathrm{argmin}_{\theta \in Y} \left\{ f(x, \theta) + g(x, \theta) + \frac{1}{2\gamma}\|\theta - y\|^2 \right\}
\end{equation}
is well-defined and single-valued  on $X \times \mathbb{R}^m$. We denote its unique solution by $\theta_\gamma^*(x, y)$.
Below, we summarize sensitivity results for $v_\gamma(x, y)$ from Theorems 2, 3, and 5 of \cite{gao2024}.

\begin{equation}\label{valuefinc}
	\nabla v_\gamma(x, y) = \Big( \nabla_x f(x, \theta_\gamma^*(x, y)) + \nabla_x g(x, \theta_\gamma^*(x, y)), \left({y - \theta_\gamma^*(x, y)}\right)/{\gamma} \Big).
\end{equation}

\begin{proposition}\label{partial_grad_v}
	Suppose Assumptions \ref{asup2} and \ref{asup3} hold. For $\gamma \in (0, 1/(\rho_{f_2} + \rho_{g_2}))$, the function $v_\gamma(x, y)$ is $\rho_{v_1}$-weakly convex with respect to $x$ on $X$ for any $y \in Y$ with $\rho_{v_1} \geq \rho_{f_1} + \rho_{g_1}$. It is also convex with respect to $y$ on $\mathbb{R}^m$ for any $x \in X$. Moreover, $v_\gamma(x, y)$ is differentiable with gradient given by \eqref{valuefinc} on $X \times \mathbb{R}^m$, and $\theta_\gamma^*(x, y)$ and $\nabla v_\gamma(x, y)$ are continuous on $X \times \mathbb{R}^m$.
\end{proposition}

\begin{definition}
	Let $(\bar{x},\bar{y})$ be a feasible solution of problem $({\rm VP})_{\gamma}^{\epsilon}$ with $\epsilon > 0$. We say that $(\bar{x},\bar{y})$ is a stationary/KKT point of problem $({\rm VP})_{\gamma}^{\epsilon}$ if there exists a multiplier $\lambda \ge 0$ such that
	\begin{equation*}
		\begin{cases}
			0\in \nabla F(\bar{x},\bar{y}) + \lambda \left(\nabla f(\bar{x},\bar{y}) + \partial g(\bar{x},\bar{y}) - \nabla v_{\gamma}(\bar{x},\bar{y})\right) + \mathcal{N}_{X\times Y}(\bar{x},\bar{y}), \\
			f(\bar{x},\bar{y}) + g(\bar{x},\bar{y}) - v_{\gamma}(\bar{x},\bar{y}) \leq \epsilon, \qquad \lambda \left(f(\bar{x},\bar{y}) + g(\bar{x},\bar{y}) - v_{\gamma}(\bar{x},\bar{y})-\epsilon\right) = 0.
		\end{cases}
	\end{equation*}
\end{definition}

In this section, we propose a new gradient-type algorithm, Alternating Gradient-type algorithm with Inexact Lower-level Solutions (AGILS), to solve ${\rm (VP)}_\gamma^\epsilon$. Given that $f(x, y) + g(x,y) - v_{\gamma}(x, y)$ is always nonnegative, a natural approach is to consider the following penalized problem,
\begin{equation}\label{penprob}
	\min_{x \in X, y \in Y}\psi_{p_k}	(x, y) := \frac{1}{p_k}F(x, y) + f(x, y) + g(x,y) - v_{\gamma}(x, y),
\end{equation}
where $p_k$ is the penalty parameter at iteration $k$. Due to the nonsmoothness of $g(x,y)$ with respect to $y$ and the availability of its proximal operator, it is natural to adopt a proximal alternating linearization method \cite{bolte2014proximal} to construct the algorithm. Given the current iterate $(x^k, y^k)$, linearizing the smooth components of $\psi_{p_k}	(x, y)$ requires evaluating gradients, including $\nabla v_{\gamma}(x, y)$ as provided in \cref{grad_v}. Calculating the exact gradient  $\nabla v_{\gamma}(x^k, y^k)$ requires solving the proximal lower-level problem in \eqref{proximal_LL} to obtain $\theta_\gamma^*(x^k, y^k)$. However, this solution typically does not have a closed-form expression, and solving it requires an iterative optimization solver, which can be computationally expensive. To address this, we propose an inexact gradient approximation by substituting $\theta_{\gamma}^*$ with an inexact estimate $\theta^k$.

The proposed algorithm alternates between updating $y$ and $x$ while refining the inexact approximation of $\theta_\gamma^*(x^k, y^k)$. At each iteration $k=0,1,\ldots$, given the current iterate $(x^k, y^k)$, along with the feasibility-corrected iterate $\tilde{y}^k$ and corresponding $\tilde{\theta}^k$ (constructed from $y^k$ and  $\theta^{k}$ via the procedure detailed below), the next iterate $(x^{k+1}, y^{k+1})$ and the refined approximation $\theta^{k+1}$ are updated as follows.

{\bf Update $y$ (Fixing $x$).}
We compute the update direction for $y$,
\begin{equation}\label{dy}
	d_y^k:= \frac{1}{p_k} \nabla_y F\left(x^{k}, \tilde{y}^k\right)+\nabla_y f\left(x^{k}, \tilde{y}^k\right)-\frac{\tilde{y}^k-\tilde{\theta}^{k}}{\gamma},
\end{equation}
where $(\tilde{y}^k-\tilde{\theta}^{k})/{\gamma}$ is an inexact approximation of $\nabla_y v_{\gamma}(x^{k}, \tilde{y}^k) =( {\tilde{y}^k} -  \theta_{\gamma}^*(x^{k}, \tilde{y}^k))/ \gamma $ (see (\ref{valuefinc})). Using $	d_y^k$, the variable $y$ is updated as
\begin{equation}\label{update_y}
	y^{k+1} = \underset{y \in Y}{\mathrm{argmin}} ~ \left\langle d_y^k, y - \tilde{y}^{k} \right\rangle + g(x^k, y) + \frac{1}{2\beta_k} \left\| y - \tilde{y}^k \right\|^2, 
\end{equation}
where $\beta_k>0$ is the stepsize. 
This can also be expressed using the proximal operator
\begin{equation}\label{update_y2}
	y^{k+1} = \operatorname{Prox}_{\beta_k\tilde{g}(x^{k},\cdot)}\left(\tilde{y}^k-\beta_k d^k_y\right),
\end{equation}
where $\tilde{g}(x,y) := g(x,y) + \delta_Y(y)$.

{\bf Find inexact approximation $\theta^{k+1/2}$.}
After updating $y^{k+1}$, we compute an inexact approximation $\theta^{k+1/2}$ for $\theta_{\gamma}^*(x^k, y^{k+1})$ by solving
\begin{equation}\label{theta_y}
	\theta^{k+1/2} \approx 	\underset{\theta \in Y}{\mathrm{argmin}} \left\{f(x^{k},\theta) + g(x^{k}, \theta) + \frac{1}{2\gamma}\left\|\theta-y^{k+1}\right\|^2\right\}, 
\end{equation}
subject to either an absolute or a relative inexactness criterion
\begin{equation}\label{inexacty1}
	\begin{aligned}
		\mathcal{G}(\theta^{k+1/2}, x^k,y^{k+1}) \le s_k, \quad \text{or} \quad \mathcal{G}(\theta^{k+1/2}, x^k,y^{k+1}) \le \tau_k \mathcal{G}(\theta^{k-1}, x^{k-1},y^{k-1}),
	\end{aligned}
\end{equation}
which can be compactly expressed as
\[
\mathcal{G}(\theta^{k+1/2}, x^{k}, y^{k+1})
\le
\max\left\{ s_k,\ \tau_k\,\mathcal{G}(\theta^{k-1}, x^{k-1}, y^{k-1}) \right\}.
\]

{\bf Update $x$ (Fixing $y$).}
We compute the update direction for $x$,
\begin{equation}\label{dx}
	d_x^k:= \frac{1}{p_k} \nabla_xF\left(x^k, y^{k+1}\right)+\nabla_x \varphi \left(x^k, y^{k+1}\right)-\nabla_x f\left(x^k, \theta^{k+1/2}\right)-\nabla_x g\left(x^k, \theta^{k+1/2}\right),
\end{equation}
where $\nabla_x f\left(x^k, \theta^{k+1/2}\right)+\nabla_x g\left(x^k, \theta^{k+1/2}\right)$ is an approximation to \( \nabla_x v_{\gamma}(x^k, y^{k+1}) = \nabla_x f(x^k, \theta^*_{\gamma}(x^k, y^{k+1}))+\nabla_x g(x^k, \theta^*_{\gamma}(x^k, y^{k+1}))\) (see \eqref{valuefinc}).
Using the direction $d_x^k$, we update $x$ with stepsize $\alpha_k>0$ as
\begin{equation}\label{update_x}
	x^{k+1}=\operatorname{Proj}_X\left(x^k-\alpha_k d_x^k\right).
\end{equation}

{\bf Find inexact approximation $\theta^{k+1}$.}
After updating $x^{k+1}$, a new inexact approximation $\theta^{k+1}$ of $\theta^*_{\gamma}(x^{k+1}, y^{k+1})$  is computed by approximately solving
\[
\theta^{k+1} \approx 	\underset{\theta \in Y}{\mathrm{argmin}} \left\{f(x^{k+1},\theta) + g(x^{k+1}, \theta) + \frac{1}{2\gamma}\left\|\theta-y^{k+1}\right\|^2\right\}, 
\]
such that $\theta^{k+1}$ satisfies either an absolute or a relative inexactness criterion
\begin{equation}\label{inexacty2}
	\begin{aligned}
		\mathcal{G}(\theta^{k+1}, x^{k+1},y^{k+1}) \le s_{k+1}, \quad \text{or} \quad  \mathcal{G}(\theta^{k+1}, x^{k+1},y^{k+1}) \le \tau_{k+1}\mathcal{G}(\theta^{k}, x^{k},y^{k}).
	\end{aligned}
\end{equation}

{\bf Penalty parameter update and feasibility correction.}
To encourage feasibility of the constraint $\varphi(x, y) - v_{\gamma}(x, y) \le \epsilon$, the penalty parameter $p_k$ is updated at each iteration.
Evaluating the constraint violation requires computing $ v_{\gamma}(x, y)$, which involves solving the proximal lower-level problem in \eqref{proximal_LL}. Instead, we use $\theta^{k+1}$ to estimate the constraint violation as
\begin{equation}\label{def_t}
	t^{k+1}=\max\left\{\varphi(x^{k+1},y^{k+1})-\varphi(x^{k+1},\theta^{k+1})-\frac{1}{2\gamma}\| \theta^{k+1} - y^{k+1}\|^2-\epsilon,0\right\}.
\end{equation}
The penalty parameter \(p_k\) is increased to $p_{k+1}=	p_k + \varrho_p$ (for some $\varrho_p > 0$) only when the change in the iterates, $\Delta_{k+1} := \left\| (x^{k+1}, y^{k+1}) - (x^k, \tilde{y}^k) \right\|$, is small relative to the penalty parameter (i.e., $\Delta_{k+1} < c_p/p_k$ for some $c_p > 0$), while the estimated constraint violation $t^{k+1}$ is large relative to this change (i.e., $t^{k+1} > \Delta_{k+1}/c_p$).
These two conditions can be compactly written as \begin{equation}\label{update_p_1}
	\Delta_{k+1} < c_p \min\left\{1/p_k,{t^{k+1}}\right\}.
\end{equation}

The feasibility correction procedure aims to generate a corrected iterate $\tilde{y}^{k+1} $ from $y^{k+1}$. It is based on the observation that if $(x^{k+1},y^{k+1})$ is feasible, then $y^{k+1}$ should be a reasonably accurate solution to the lower-level problem \eqref{LL}  for $x= x^{k+1}$, implying that $\| \nabla_y v_{\gamma}(x^{k+1},y^{k+1})\| $ should be small. We use the magnitude of $( y^{k+1} - \theta^{k+1})/\gamma$ to approximate $\| \nabla_y v_{\gamma}(x^{k+1},y^{k+1})\| $. The feasibility correction  is triggered if:
\begin{equation}\label{theta_gap_condition}
	\left\| y^{k+1} - \theta^{k+1} \right\| \ge \frac{c_y \gamma}{p_k},
\end{equation}
where $c_y > 0$. Condition \eqref{theta_gap_condition} indicates that the iterate $(x^{k+1},y^{k+1})$ might be approaching an undesirable stationary point of the constraint function.

If condition \eqref{theta_gap_condition} holds, we attempt to correct $y^{k+1}$ by finding a candidate iterate $\tilde{y}^{k+1} $  as an inexact solution to the lower-level problem \eqref{LL} with $x= x^{k+1}$ satisfying
\begin{equation}\label{inexacty_y}
	\left\| \tilde{y}^{k+1} - \operatorname{Prox}_{ \tilde{g}(x^{k+1}, \cdot)} \left( \tilde{y}^{k+1} -  \nabla_y f(x^{k+1}, \tilde{y}^{k+1}) \right) \right\| \le \frac{c_{\tilde{y}} }{p_k} \Delta_{k+1}, 
\end{equation}

where $c_{\tilde{y}} > 0$. However, unconditionally accepting such a $\tilde{y}^{k+1} $ could adversely affect the algorithm's convergence. Therefore, to preserve convergence, $\tilde{y}^{k+1} $ is accepted only if it satisfies the following descent condition
\begin{equation}\label{decrease_new_y}
	\begin{aligned}
		&\frac{1}{p_k}F(x^{k+1}, \tilde{y}^{k+1}) + \varphi(x^{k+1}, \tilde{y}^{k+1}) - \left( \varphi(x^{k+1},  \tilde{\theta}^{k+1} ) + \frac{1}{2\gamma} \| \tilde{\theta}^{k+1} - \tilde{y}^{k+1} \|^2 \right)\\
		\le\; &
		\frac{1}{p_k}F(x^{k+1}, y^{k+1}) + \varphi(x^{k+1}, y^{k+1}) - \left( \varphi(x^{k+1}, \theta^{k+1}) + \frac{1}{2\gamma} \| \theta^{k+1} - y^{k+1} \|^2 \right),
	\end{aligned}
\end{equation}

where, $\tilde{\theta}^{k+1}$ is a new approximation of $\theta^*_{\gamma}(x^{k+1}, \tilde{y}^{k+1})$. We construct $\tilde{\theta}^{k+1}$ by first finding a point $\hat{\theta}^{k+1}$ that satisfies the inexactness criterion
\begin{equation}\label{inexacty3}
	\mathcal{G}(\hat{\theta}^{k+1}, x^{k+1},\tilde{y}^{k+1}) \le s_{k+1},
	\quad \text{or} \quad
	\mathcal{G}(\hat{\theta}^{k+1}, x^{k+1},\tilde{y}^{k+1})
	\le \tau_{k+1}\mathcal{G}(\theta^{k}, x^{k},y^{k}).
\end{equation}
and subsequently applying a single proximal-gradient step to $\hat{\theta}^{k+1}$
\[
\tilde{\theta}^{k+1}
=
\operatorname{Prox}_{\eta \tilde g(x^{k+1},\cdot)}
\left(
\hat{\theta}^{k+1}
-\eta\left(
\nabla_y f(x^{k+1},\hat{\theta}^{k+1})
+\frac{\hat{\theta}^{k+1}-\tilde y^{k+1}}{\gamma}
\right)
\right).
\]

\begin{algorithm}[htp!]
\caption{Alternating Gradient-type algorithm with Inexact Lower-level Solutions (AGILS)}
\label{alg1}
\begin{algorithmic}[1]
	\STATE{{\bf Input}: Initial iterates $x^0,\theta^{-1}, y^0, \tilde{\theta}^0, \tilde{y}^0$, set $(x^{-1}, y^{-1}, \theta^{-1}) = (x^0, y^0, \tilde{\theta}^0)$, stepsizes $\alpha_k, \beta_k$, relaxation parameter $\epsilon$, proximal parameter $\gamma$, penalty parameters $p_{0}$,  $\varrho_p$, $c_p$, $c_y$, inexact parameters $\eta$, $s_{k}$, $\tau_k$, tolerance $tol$.}
	\FOR{$k=0,\ 1,\cdots$}
	\STATE{Construct the direction $d_y^k$ according to \eqref{dy}, and update $y^{k+1}$ as
		$$
		y^{k+1} = \operatorname{Prox}_{\beta_k\tilde{g}(x^{k,\cdot})}\left(\tilde{y}^k-\beta_k d^k_y\right).
		$$}

	\STATE{Find an inexact solution $\theta^{k+1/2}$ that satisfies the inexactness criterion \eqref{inexacty1}.}

	\STATE{Construct the direction $d_x^k$ according to \eqref{dx}, and update $x^{k+1}$ as 
		$$ x^{k+1}=\operatorname{Proj}_X\left(x^k-\alpha_k d_x^k\right). 
		$$}

	\STATE{Find an inexact solution $\theta^{k+1}$ that satisfies the inexactness criterion \eqref{inexacty2}.}

	\STATE{Calculate $\Delta_{k+1} := \left\| (x^{k+1}, y^{k+1}) - (x^k, \tilde{y}^k) \right\|$ and $t^{k+1}$ according to \eqref{def_t}. \\
		Stop when $k \ge 1$ and \(\max\{\Delta_{k+1}, s_{k}, t^{k+1} \} \le tol.\)
	}
	\STATE{Update penalty parameter and apply feasibility correction:}

	\STATE{\hspace*{10pt}\textbf{Case 1:}
		$\Delta_{k+1} \geq c_p \min\big\{1/p_k,\, t^{k+1} \big\}$ \\
		\vspace*{1pt}
		\qquad\qquad\quad Set \( p_{k+1} := p_k \), \( \tilde{y}^{k+1} := y^{k+1} \), \(\tilde{\theta}^{k+1} :=\theta^{k+1}\).}
	\vspace*{2pt}
	\STATE{\hspace*{10pt}\textbf{Case 2:} 
		$\Delta_{k+1} < c_p \min\big\{1/p_k,\, t^{k+1} \big\},\,\| y^{k+1} - \theta^{k+1} \| \le c_y \gamma/p_k$\\  
		\vspace*{1pt}
		\qquad\qquad\quad Set \( p_{k+1} := p_k + \varrho_p \), \( \tilde{y}^{k+1} := y^{k+1} \), \(\tilde{\theta}^{k+1} :=\theta^{k+1}\).}
	\vspace*{2pt}

	\STATE{\hspace*{10pt}\textbf{Case 3:} 
		$\Delta_{k+1} < c_p \min\big\{1/p_k,\, t^{k+1} \big\},\,\| y^{k+1} - \theta^{k+1} \| > c_y \gamma/p_k$\\
		\vspace*{1pt}
		\qquad\qquad\quad Apply the feasibility correction procedure (Algorithm~\ref{alg2}).}
\ENDFOR
\RETURN $(x^{k+1},\tilde{y}^{k+1})$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[htp!]
\caption{Feasibility Correction Procedure}
\label{alg2}
\begin{algorithmic}[1]

\STATE{{\bf Input}: Current iterates $x^{k+1}, y^{k+1}, \theta^{k+1}$, $\Delta_{k+1}$, proximal parameter $\gamma$, penalty parameters $p_{k}$, $\varrho_p$, inexact parameters $\eta$, $s_{k}$, $\tau_k$, constant $c_{\tilde{y}}$.}

\STATE{Compute a candidate $\tilde{y}^{k+1}$ by inexactly solving the lower-level problem \eqref{LL} with $x=x^{k+1}$  to satisfy \eqref{inexacty_y}.
}

\STATE{Find an intermediate point $\hat{\theta}^{k+1}$ that satisfies the inexactness criterion \eqref{inexacty3}, and compute $\tilde{\theta}^{k+1}=
\operatorname{Prox}_{\eta \tilde g(x^{k+1},\cdot)}
(
\hat{\theta}^{k+1}
-\eta(
\nabla_y f(x^{k+1},\hat{\theta}^{k+1})
+(\hat{\theta}^{k+1}-\tilde y^{k+1})/\gamma
)
)$.}

\IF{the descent condition \eqref{decrease_new_y} holds}
\STATE{Accept the candidate: Set $p_{k+1} := p_k$.}
\ELSE
\STATE{Reject the candidate: Set $\tilde{y}^{k+1} := y^{k+1}$, $\tilde{\theta}^{k+1} := \theta^{k+1}$ and $p_{k+1} := p_k + \varrho_p$.}
\ENDIF
\RETURN $(\tilde{y}^{k+1},\tilde{\theta}^{k+1},p_{k+1})$
\end{algorithmic}
\end{algorithm}

We now proceed to establish a decreasing property for the proposed method based on the following merit function:
\begin{equation*}
	\tilde{\psi}_{p_{k}}(x,y) :=\frac{1}{p_k}(F(x,y)-\underline{F})+ f(x,y) + g(x,y)-v_{\gamma}(x,y).
\end{equation*}

Before establishing the main decreasing property, we first demonstrate that the descent condition \eqref{decrease_new_y}, imposed by the feasibility correction procedure (Algorithm \ref{alg2}), ensures a decrease in $\tilde{\psi}_{p_{k}}$ when moving from $y^{k+1}$ to the corrected iterate $\tilde{y}^{k+1} $.

\begin{lemma}\label{lem0}
	Suppose Assumptions \ref{asup2} and \ref{asup3} hold. Then, there exists $C_\gamma>0$,  such that the sequence $\{(x^k,y^k,\tilde{y}^k)\}$ generated by AGILS (\cref{alg1}) satisfies
	\begin{equation}\label{lem1_eq12}
		\tilde{\psi}_{p_k}(x^{k+1}, \tilde{y}^{k+1}) \le  \tilde{\psi}_{p_k}(x^{k+1}, y^{k+1}) + C_{\gamma} \zeta_{k+1}^2,
	\end{equation}
	where  $\zeta_{k} := \max\{ s_k,  ( \prod_{i=0}^{k} \tau_i ) \mathcal{G}(\theta^{0}, x^{0}, y^{0})\}$.
\end{lemma}

\begin{lemma}\label{lem9}
	Suppose Assumptions \ref{asup2} and \ref{asup3} hold. Let $\gamma \in (0, 1/(\rho_{f_2} +\rho_{g_2}) )$ and  $(\bar{x},\bar{y})\in X\times \Re^m$. Then, for any $(x,y) \in X \times \Re^m$, the following inequalities hold,
	\begin{align}
		-v_{\gamma}(x,\bar{y}) &\le -v_{\gamma}(\bar{x},\bar{y})-\langle \nabla_x v_{\gamma}(\bar{x},\bar{y}),x-\bar{x}\rangle +\frac{\rho_{f_1} + \rho_{g_1}}{2}\|\bar{x}-x\|^2,  \label{lem9_eq1} \\

		-v_{\gamma}(\bar{x},y) &\le -v_{\gamma}(\bar{x},\bar{y})-\langle \nabla_y v_{\gamma}(\bar{x},\bar{y}),y-\bar{y}\rangle. \label{lem9_eq2}
	\end{align}
\end{lemma}

\begin{proof}
	According to Proposition \ref{partial_grad_v}, for any $\bar{y} \in \Re^m$, $v_{\gamma}(x, \bar{y})$ is a $(\rho_{f_1} + \rho_{g_1})$-weakly convex function with respect to $x$ on $X$, that is, $v_{\gamma}(x,\bar{y})+\frac{\rho_{f_1} + \rho_{g_1}}{2}\|x\|^2$ is convex on $X$. Then we can obtain \eqref{lem9_eq1} immediately. The second inequality \eqref{lem9_eq2} follows from Proposition \ref{partial_grad_v} that for any $\bar{x} \in X$, $v_{\gamma}(\bar{x}, y)$ is convex with respect to $y$.
\end{proof}

\begin{lemma}\label{lem1}
	Suppose Assumptions \ref{asup1}, \ref{asup2} and \ref{asup3} hold. Let $\gamma \in (0, 1/(\rho_{f_2} +\rho_{g_2}) )$, $\alpha_k \in [0, 2/(L_{\psi_{x,k}} + c_\alpha)]$ and $\beta_k \in [0, 2/(L_{\psi_{y,k}} + c_\beta)]$, where $L_{\psi_{x,k}} = L_{F_x}/p_k+L_{f_x}+L_{g_1}+\rho_{f_1} + \rho_{g_1}$, $L_{\psi_{y,k}} = L_{F_y}/p_k+L_{f_y}$ and $c_\alpha, c_\beta$ are positive constants. Then, there exists $C_\eta , C_\gamma > 0$ such that the sequence $\{(x^k,y^k,\tilde{y}^k)\}$ generated by AGILS {\rm (}\cref{alg1}{\rm )} satisfies the following inequality,
	\begin{equation}\label{lem1_eq}
		\begin{aligned}
			\tilde{\psi}_{p_{k+1}}\left(x^{k+1}, \tilde{y}^{k+1}\right)\leq\,& \tilde{\psi}_{p_k}\left(x^k, \tilde{y}^k\right) +  \left( \frac{C_\eta^2}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{C_\eta^2}{c_\beta\gamma^2 } \right) \zeta_{k}^2 + C_{\gamma} \zeta_{k+1}^2\\
			&- \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2  -\frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2,
		\end{aligned}
	\end{equation}
	where  $\zeta_{k} := \max\{ s_k,  ( \prod_{i=0}^{k} \tau_i ) \mathcal{G}(\theta^{0}, x^{0}, y^{0})\}$ and $\{ \zeta_{k} \}$ is square summable.
\end{lemma}

\begin{proof}

	First, the update rule for \( y^{k+1} \) given in \eqref{update_y} defines it as the minimizer of the function $ g(x^k, y) + \langle d_y^k, y - \tilde{y}^{k} \rangle + \frac{1}{2\beta_k} \left\| y - \tilde{y}^k \right\|^2$. This function is $1/\beta_k$-strongly convex in $y$. By applying \cite[Theorem 6.39]{beck2017first}, we obtain
	\begin{equation}\label{lem1_eq5}
		g(x^{k}, y^{k+1}) + \langle d_y^k, y^{k+1}-\tilde{y}^k\rangle+\frac{1}{\beta_k}\|y^{k+1}-\tilde{y}^k\|^2 \le g(x^{k}, \tilde{y}^{k}).
	\end{equation}


	According to the assumptions, with $x^{k} \in X$, we have that $\nabla_y F(x^{k},y)$ and $\nabla_y f(x^{k},y)$ are $L_{F_y}$- and  $L_{f_y}$-Lipschitz continuous with respect to variable $y$ on $Y$, respectively, and combine this with \eqref{lem9_eq2}, we have
	\begin{equation}\label{lem1_eq6}
		\begin{aligned}
			&(\tilde{\psi}_{p_k}-g)(x^{k},y^{k+1})  \\
			\le \, & (\tilde{\psi}_{p_k}-g)	(x^{k},\tilde{y}^k) + \langle \nabla_y (\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k),y^{k+1}-\tilde{y}^k\rangle +\frac{L_{\psi_{y,k}}}{2}\|y^{k+1}-\tilde{y}^k\|^2,
		\end{aligned}
	\end{equation}
	where $L_{\psi_{y,k}}=L_{F_y}/p_k+L_{f_y}$. 
	Combining \eqref{lem1_eq5} and \eqref{lem1_eq6} yields
	\begin{equation}\label{lem1_eq7}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,& 	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right) + \langle \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k, y^{k+1}-\tilde{y}^k\rangle  \\
			&-\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
		\end{aligned}
	\end{equation}	
	Using the formula of \( \nabla_y v_\gamma \) in \eqref{valuefinc}, and the construction of $d_y^k$ in \eqref{dy}, we have
	\begin{equation}\label{lem1_eq11}
		\begin{aligned}
			\left\| \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k \right\| & = \| \nabla_y v_\gamma(x^k, \tilde{y}^k) + (\tilde{y}^k-\theta^{k})/\gamma\| \\
			& = \frac{1}{\gamma}\left\| \theta^*_{\gamma}(x^{k},\tilde{y}^k) - \theta^{k} \right\| \le \frac{C_\eta}{\gamma} \mathcal{G}({\theta}^{k}, x^{k}, \tilde{y}^{k}) \le \frac{C_\eta}{\gamma} \zeta_{k},
		\end{aligned}
	\end{equation}
	where the first inequality follows from Lemma \ref{error_bound} and the second inequality is a consequence of the inexactness condition \eqref{inexacty2}. 

	Combining the above inequality with \eqref{lem1_eq7} gives us
	\begin{equation}\label{lem1_eq8}
		\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,  	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right)  - \left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2.
	\end{equation}
	Next, considering the update rule for $x^{k+1}$ given in \eqref{update_x}, we have
	\begin{equation}\label{lem1_eq1}
		\langle d_x^k, x^{k+1}-x^k\rangle+\frac{1}{\alpha_k}\|x^{k+1}-x^k\|^2 \le 0.
	\end{equation}	
	By the assumptions, with $y^{k+1} \in Y$, we have that $\nabla_x F(x, y^{k+1})$, $\nabla_x f(x, y^{k+1})$ and $\nabla_{x} g(x, y^{k+1})$ are $L_{F_x}$-, $L_{f_x}$-, and $L_{g_1}$-Lipschitz continuous with respect to variable $x$ on $X$, respectively, and combine this with \eqref{lem9_eq1}, we have
	\begin{equation}\label{lem1_eq2}
		\tilde{\psi}_{p_k}(x^{k+1}, y^{k+1})\le  \tilde{\psi}_{p_k}	(x^{k}, y^{k+1})+\langle \nabla_x 	\tilde{\psi}_{p_k}(x^{k}, y^{k+1}),x^{k+1}-x^k\rangle+\frac{L_{\psi_{x,k}}}{2}\|x^{k+1}-x^k\|^2,
	\end{equation}
	where $L_{\psi_{x,k}}=L_{F_x}/p_k+L_{f_x}+L_{g_1}+ \rho_{f_1} + \rho_{g_1} $. Combining \eqref{lem1_eq1} and \eqref{lem1_eq2} yields
	\begin{equation}\label{lem1_eq3}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) + \langle \nabla_x \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k,x^{k+1}-x^k\rangle  \\
			&-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}\right)\left\|x^{k+1}-x^k\right\|^2.
		\end{aligned}
	\end{equation}
	Using the formula of the gradient of $v_\gamma$ given in \eqref{valuefinc} and the construction of $d_x^k$ in \eqref{dx}, and the $L_{f_x}$- and $L_{g_2}$-Lipschitz continuity of $\nabla_x f(x^k,y)$ and $\nabla_{x} g(x^k,y)$ with respect to variable $y$ on $Y$, we have
	\begin{equation}\label{lem1_eq10}
		\begin{aligned}
			\left\| \nabla_x  \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k \right\| 
			&= \left\| \nabla_{x} \varphi(x^k, \theta^*_{\gamma}(x^k,y^{k+1})) - \nabla_{x} \varphi(x^k, \theta^{k+1/2}) \right\| \\
			& \le (L_{f_x} + L_{g_2})\left\| \theta^*_{\gamma}(x^k,y^{k+1}) - \theta^{k+1/2} \right\| \le (L_{f_x} + L_{g_2})C_\eta \zeta_{k},
		\end{aligned}
	\end{equation}
	where the last inequality follows from \cref{error_bound} and the inexact criterion \eqref{inexacty1}. Combining the above inequality with \eqref{lem1_eq3} gives us
	\begin{equation}\label{lem1_eq4}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) - \left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}-\frac{c_\alpha}{4}\right)\left\|x^{k+1}-x^k\right\|^2 \\ & + \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2.
		\end{aligned}
	\end{equation}
	Combining  \eqref{lem1_eq8}, \eqref{lem1_eq4}, and then  \eqref{lem1_eq12} established in  Lemma \ref{lem0}, we obtain
	\begin{equation}\label{lem1_eq9}
		\begin{aligned}
			\tilde{\psi}_{p_k}\left(x^{k+1}, \tilde{y}^{k+1}\right)\leq\,& 	\tilde{\psi}_{p_k}\left(x^k, \tilde{y}^k\right)+  \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2 + C_{\gamma} \zeta_{k+1}^2\\
			&\hspace{-50pt}-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}- \frac{c_\alpha}{4} \right)\left\|x^{k+1}-x^k\right\|^2 -\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4} \right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
		\end{aligned}
	\end{equation}
	Because  $\alpha_k \in [0, 2/(L_{\psi_{x,k}} + c_\alpha)]$ and $\beta_k \in [0, 2/(L_{\psi_{y,k}} + c_\beta)]$, and $\tilde{\psi}_{p_{k+1}}(x^{k+1}, \tilde{y}^{k+1}) \leq 	\tilde{\psi}_{p_k}(x^{k+1}, \tilde{y}^{k+1})$ following from the non-decreasing property of the penalty parameter $p_k$ and the non-negative property of $F-\underline{F}$, we can obtain \eqref{lem1_eq} from \eqref{lem1_eq9}.

	Finally, we show that \( \{\zeta_k\} \) is square summable. Let $ \mathcal{G}_0 = \mathcal{G}(\theta^{0}, x^{0}, y^{0})$ and $r_k :=  ( \prod_{i=0}^{k} \tau_i )\mathcal{G}_0 $. Since $\zeta_{k} := \max\{ s_k, r_k\}$, we have $\sum_{k=0}^\infty \zeta_k^2 \le \sum_{k=0}^\infty s_k^2 + \sum_{k=0}^\infty r_k^2$. By assumption, \( \sum_{k=0}^\infty s_k^2 < \infty \). Thus, we only need to show that  \( \{r_k\} \) is square summable. Recall that \( \tau_k = \tau_0/(k+1)^{p_\tau} \) with \( p_\tau > 0 \), then
	\[
	r_k = \left( \prod_{i=0}^{k} \tau_i \right) \mathcal{G}_0  = \tau_0^{k+1} \left( \prod_{i=1}^{k+1} \frac{1}{i^{p_\tau}} \right) \cdot \mathcal{G}_0  = \frac{\tau_0^{k+1}}{((k+1)!)^{p_\tau}}\mathcal{G}_0 .
	\]
	For the ratio test on  $\sum_{k=0}^\infty r_k^2$, we consider 
	\[
	\lim_{k \rightarrow \infty}\frac{r_{k+1}^2}{r_k^2} =  \lim_{k \rightarrow \infty} \frac{\tau_0^2}{(k+2)^{2p_\tau}}  = 0.
	\]
	Therefore, by the ratio test, $\sum_{k=0}^\infty r_k^2 < \infty$, implying that \( \{\zeta_k\} \) is square summable.
\end{proof}

\begin{proof}

	First, the update rule for \( y^{k+1} \) given in \eqref{update_y} defines it as the minimizer of the function $ g(x^k, y) + \langle d_y^k, y - \tilde{y}^{k} \rangle + \frac{1}{2\beta_k} \left\| y - \tilde{y}^k \right\|^2$. This function is $1/\beta_k$-strongly convex in $y$. By applying \cite[Theorem 6.39]{beck2017first}, we obtain
	\begin{equation}\label{lem1_eq5}
		g(x^{k}, y^{k+1}) + \langle d_y^k, y^{k+1}-\tilde{y}^k\rangle+\frac{1}{\beta_k}\|y^{k+1}-\tilde{y}^k\|^2 \le g(x^{k}, \tilde{y}^{k}).
	\end{equation}

According to the assumptions, with $x^{k} \in X$, we have that $\nabla_y F(x^{k},y)$ and $\nabla_y f(x^{k},y)$ are $L_{F_y}$- and  $L_{f_y}$-Lipschitz continuous with respect to variable $y$ on $Y$, respectively, and combine this with \eqref{lem9_eq2}, we have
\begin{equation}\label{lem1_eq6}
	\begin{aligned}
		&(\tilde{\psi}_{p_k}-g)(x^{k},y^{k+1})  \\
		\le \, & (\tilde{\psi}_{p_k}-g)	(x^{k},\tilde{y}^k) + \langle \nabla_y (\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k),y^{k+1}-\tilde{y}^k\rangle +\frac{L_{\psi_{y,k}}}{2}\|y^{k+1}-\tilde{y}^k\|^2,
	\end{aligned}
\end{equation}
where $L_{\psi_{y,k}}=L_{F_y}/p_k+L_{f_y}$.

Combining \eqref{lem1_eq5} and \eqref{lem1_eq6} yields
\begin{equation}\label{lem1_eq7}
	\begin{aligned}
		\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,& 	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right) + \langle \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k, y^{k+1}-\tilde{y}^k\rangle  \\
		&-\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
	\end{aligned}
\end{equation}

Using the formula of \( \nabla_y v_\gamma \) in \eqref{valuefinc}, and the construction of $d_y^k$ in \eqref{dy}, we have
\begin{equation}\label{lem1_eq11}
	\begin{aligned}
		\left\| \nabla_y (	\tilde{\psi}_{p_k}-g)(x^{k},\tilde{y}^k) - d_y^k \right\| & = \| \nabla_y v_\gamma(x^k, \tilde{y}^k) + (\tilde{y}^k-\theta^{k})/\gamma\| \\
		& = \frac{1}{\gamma}\left\| \theta^*_{\gamma}(x^{k},\tilde{y}^k) - \theta^{k} \right\| \le \frac{C_\eta}{\gamma} \mathcal{G}({\theta}^{k}, x^{k}, \tilde{y}^{k}) \le \frac{C_\eta}{\gamma} \zeta_{k},
	\end{aligned}
\end{equation}
where the first inequality follows from Lemma \ref{error_bound} and the second inequality is a consequence of the inexactness condition \eqref{inexacty2}.


Combining the above inequality with \eqref{lem1_eq7} gives us
\begin{equation}\label{lem1_eq8}
	\tilde{\psi}_{p_k}\left(x^{k}, y^{k+1}\right) \leq \,  	\tilde{\psi}_{p_k}\left(x^{k}, \tilde{y}^k\right)  - \left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4}\right)\left\|y^{k+1}-\tilde{y}^k\right\|^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2.
\end{equation}

Next, considering the update rule for $x^{k+1}$ given in \eqref{update_x}, we have
\begin{equation}\label{lem1_eq1}
	\langle d_x^k, x^{k+1}-x^k\rangle+\frac{1}{\alpha_k}\|x^{k+1}-x^k\|^2 \le 0.
\end{equation}	
By the assumptions, with $y^{k+1} \in Y$, we have that $\nabla_x F(x, y^{k+1})$, $\nabla_x f(x, y^{k+1})$ and $\nabla_{x} g(x, y^{k+1})$ are $L_{F_x}$-, $L_{f_x}$-, and $L_{g_1}$-Lipschitz continuous with respect to variable $x$ on $X$, respectively, and combine this with \eqref{lem9_eq1}, we have
\begin{equation}\label{lem1_eq2}
	\tilde{\psi}_{p_k}(x^{k+1}, y^{k+1})\le  \tilde{\psi}_{p_k}	(x^{k}, y^{k+1})+\langle \nabla_x 	\tilde{\psi}_{p_k}(x^{k}, y^{k+1}),x^{k+1}-x^k\rangle+\frac{L_{\psi_{x,k}}}{2}\|x^{k+1}-x^k\|^2,
\end{equation}
where $L_{\psi_{x,k}}=L_{F_x}/p_k+L_{f_x}+L_{g_1}+ \rho_{f_1} + \rho_{g_1} $. Combining \eqref{lem1_eq1} and \eqref{lem1_eq2} yields

\begin{equation}\label{lem1_eq3}
	\begin{aligned}
		\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) + \langle \nabla_x \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k,x^{k+1}-x^k\rangle  \\
		&-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}\right)\left\|x^{k+1}-x^k\right\|^2.
	\end{aligned}
\end{equation}

Using the formula of the gradient of $v_\gamma$ given in \eqref{valuefinc} and the construction of $d_x^k$ in \eqref{dx}, and the $L_{f_x}$- and $L_{g_2}$-Lipschitz continuity of $\nabla_x f(x^k,y)$ and $\nabla_{x} g(x^k,y)$ with respect to variable $y$ on $Y$, we have
\begin{equation}\label{lem1_eq10}
	\begin{aligned}
		\left\| \nabla_x  \tilde{\psi}_{p_k}(x^{k},y^{k+1}) - d_x^k \right\| 
		&= \left\| \nabla_{x} \varphi(x^k, \theta^*_{\gamma}(x^k,y^{k+1})) - \nabla_{x} \varphi(x^k, \theta^{k+1/2}) \right\| \\
		& \le (L_{f_x} + L_{g_2})\left\| \theta^*_{\gamma}(x^k,y^{k+1}) - \theta^{k+1/2} \right\| \le (L_{f_x} + L_{g_2})C_\eta \zeta_{k},
	\end{aligned}
\end{equation}
where the last inequality follows from \cref{error_bound} and the inexact criterion \eqref{inexacty1}. Combining the above inequality with \eqref{lem1_eq3} gives us

\begin{equation}\label{lem1_eq4}
	\begin{aligned}
		\tilde{\psi}_{p_k}\left(x^{k+1}, y^{k+1}\right) \leq \,& \tilde{\psi}_{p_k}\left(x^k, y^{k+1}\right) - \left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}-\frac{c_\alpha}{4}\right)\left\|x^{k+1}-x^k\right\|^2 \\ & + \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2.
	\end{aligned}
\end{equation}

Combining  \eqref{lem1_eq8}, \eqref{lem1_eq4}, and then  \eqref{lem1_eq12} established in  Lemma \ref{lem0}, we obtain
\begin{equation}\label{lem1_eq9}
	\begin{aligned}
		\tilde{\psi}_{p_k}\left(x^{k+1}, \tilde{y}^{k+1}\right)\leq\,& 	\tilde{\psi}_{p_k}\left(x^k, \tilde{y}^k\right)+  \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2C_\eta^2 \zeta_{k}^2 + \frac{C_\eta^2}{c_\beta\gamma^2} \zeta_{k}^2 + C_{\gamma} \zeta_{k+1}^2\\
		&\hspace{-50pt}-\left(\frac{1}{\alpha_k}-\frac{L_{\psi_{x,k}}}{2}- \frac{c_\alpha}{4} \right)\left\|x^{k+1}-x^k\right\|^2 -\left(\frac{1}{\beta_k}-\frac{L_{\psi_{y,k}}}{2}- \frac{c_\beta}{4} \right)\left\|y^{k+1}-\tilde{y}^k\right\|^2.
	\end{aligned}
\end{equation}
Because  $\alpha_k \in [0, 2/(L_{\psi_{x,k}} + c_\alpha)]$ and $\beta_k \in [0, 2/(L_{\psi_{y,k}} + c_\beta)]$, and $\tilde{\psi}_{p_{k+1}}(x^{k+1}, \tilde{y}^{k+1}) \leq 	\tilde{\psi}_{p_k}(x^{k+1}, \tilde{y}^{k+1})$ following from the non-decreasing property of the penalty parameter $p_k$ and the non-negative property of $F-\underline{F}$, we can obtain \eqref{lem1_eq} from \eqref{lem1_eq9}.

\begin{lemma}\label{lem3}
	The sequence $\left\{(x^k,y^k,\tilde{y}^k)\right\}$ satisfies
	\begin{equation*}
		\sum\limits_{k=0}^{{\infty}}\left\|(x^{k+1},y^{k+1})-(x^k,\tilde{y}^k)\right\|^2<\infty, \quad \text{and} \quad \lim\limits_{k\to\infty}\left\|(x^{k+1},y^{k+1})-(x^k,\tilde{y}^k)\right\|=0.
	\end{equation*}
\end{lemma}

\begin{proof}
	Summing  \cref{lem1_eq} from Lemma \ref{lem1} over $k=0,1,\dots,K-1$ yields,
	\begin{equation}\label{lem3_eq1}
		\begin{aligned}
			\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right)- \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) \leq & -\sum\limits_{k=0}^{K-1} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right)\\& +\sum\limits_{k=0}^{K-1}\left( \frac{C_\eta^2 }{c_\alpha}(L_{f_x} + L_{g_2})^2+ \frac{C_\eta^2}{c_\beta\gamma^2} \right) \zeta_{k}^2+ \sum\limits_{k=0}^{K-1}C_{\gamma} \zeta_{k+1}^2.\\
		\end{aligned}
	\end{equation}
	Since \( \{\zeta_k\} \) is square summable from Lemma \ref{lem1}, it follows that
	\[
	\sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2 < \infty.
	\]
	Additionally, because $\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right) \ge 0$, by taking $K \rightarrow \infty$ in \eqref{lem3_eq1}, we have
	\begin{equation}\label{lem3_eq2}
		\begin{aligned}
			&\quad\,\sum\limits_{k=0}^{\infty} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right) \\
			&\le \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) + \sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2  < \infty,
		\end{aligned}
	\end{equation}
	which proves the result.
\end{proof}

\begin{proof}
	Summing  \cref{lem1_eq} from Lemma \ref{lem1} over $k=0,1,\dots,K-1$ yields,
	\begin{equation}\label{lem3_eq1}
		\begin{aligned}
			\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right)- \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) \leq & -\sum\limits_{k=0}^{K-1} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right)\\& +\sum\limits_{k=0}^{K-1}\left( \frac{C_\eta^2 }{c_\alpha}(L_{f_x} + L_{g_2})^2+ \frac{C_\eta^2}{c_\beta\gamma^2} \right) \zeta_{k}^2+ \sum\limits_{k=0}^{K-1}C_{\gamma} \zeta_{k+1}^2.\\
		\end{aligned}
	\end{equation}

	Since \( \{\zeta_k\} \) is square summable from Lemma \ref{lem1}, it follows that
	\[
	\sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2 < \infty.
	\]
	Additionally, because $\tilde{\psi}_{p_{K}}\left(x^{K}, \tilde{y}^{K}\right) \ge 0$, by taking $K \rightarrow \infty$ in \eqref{lem3_eq1}, we have
	\begin{equation}\label{lem3_eq2}
		\begin{aligned}
			&\quad\,\sum\limits_{k=0}^{\infty} \left(  \frac{c_\alpha}{4} \left\|x^{k+1}-x^k\right\|^2+ \frac{c_\beta}{4} \left\|y^{k+1}-\tilde{y}^k\right\|^2\right) \\
			&\le \tilde{\psi}_{p_{0}}\left(x^{0}, \tilde{y}^{0}\right) + \sum\limits_{k=0}^{\infty} \left( \frac{1}{c_\alpha}(L_{f_x} + L_{g_2})^2 + \frac{1}{c_\beta\gamma^2} \right) C_\eta^2\zeta_{k}^2 + \sum\limits_{k=0}^{\infty}  C_{\gamma} \zeta_{k+1}^2  < \infty,
